INSERT INTO items (id, display_id, owner_id, title, description, price_kopeks, status, attributes, is_seed, ai_verified, created_at, updated_at) VALUES
    ('4f6591a0-f17a-5a9a-9630-f89748630691', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000001', 'iPhone 13 128GB, синий, полный комплект',
     'Продаю iPhone 13 на 128 ГБ в синем цвете. Купил в официальном магазине в марте, есть чек и коробка. Экран без царапин, всегда носил в чехле со стеклом. Батарея держит 89% ёмкости — проверял в настройках при вас. Face ID, обе камеры и динамики работают без нареканий. В комплекте оригинальный кабель, отдам ещё беспроводные наушники в подарок. Причина продажи — перехожу на Android, интересно попробовать. Торг небольшой при осмотре.',
     4750000, 'published', '{"category":"electronics","condition":"used"}'::jsonb, true, false, now() - interval '60 days', now() - interval '60 days'),
    ('bd86ecbe-8ec8-52cc-9fd6-cb0829b72917', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000002', 'Стиральная машина Bosch Serie 4, 7 кг',
     'Стиральная машина Bosch Serie 4 загрузкой 7 кг, встраиваемая. Отработала три года без единого ремонта, всегда чистил фильтр и отсек для порошка. Все программы работают, отжим до 1200 об/мин, есть режим быстрой стирки и деликатных тканей. Барабан без запаха и накипи — регулярно прогонял с лимонной кислотой. Продаю в связи с переездом на съёмную квартиру с готовой техникой. Самовывоз, помогу отключить и вынести до машины.',
     2300000, 'published', '{"category":"appliances","condition":"used"}'::jsonb, true, false, now() - interval '59 days', now() - interval '59 days'),
    ('85c07331-96a0-5e3d-9a4a-1836e720ccec', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000003', 'Угловой диван велюровый, серый, раскладной',
     'Угловой диван в сером велюре, механизм еврокнижка с ящиком для белья. Купили полтора года назад, сидели аккуратно, следов от когтей и пятен нет — животных не держим. Пружинный блок мягкий, но не продавленный, спальное место ровное без бугров. Угол можно переставить на другую сторону, крепления штатные в комплекте. Продаём из-за смены планировки в новой квартире, диван туда просто не вписывается по размеру. Вывоз своими силами, подъезд и лифт грузовые есть.',
     3490000, 'published', '{"category":"furniture","condition":"used"}'::jsonb, true, false, now() - interval '58 days', now() - interval '58 days'),
    ('31631631-1cbf-5b06-a8b2-d280db6e666f', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000004', 'Пуховик мужской зимний, тёмно-синий, 52 размер',
     'Мужской зимний пуховик, размер 52, тёмно-синий с капюшоном на меху. Носил одну зиму, не порвался, наполнитель не сбился в комья. Молния плавная, кнопки все на месте, манжеты не растянуты. Внутри есть карман на молнии для телефона. Проверен на морозе до −28, замерзать не приходилось. Продаю, потому что похудел и модель стала велика в плечах. Стирал перед продажей в специальном режиме для пуховых изделий.',
     680000, 'published', '{"category":"clothes","condition":"used"}'::jsonb, true, false, now() - interval '57 days', now() - interval '57 days'),
    ('bec8c5b9-ec39-54f5-981d-20bee1ae6562', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000005', 'Коляска 2 в 1 для новорождённого, серо-бежевая',
     'Коляска-трансформер 2 в 1: люлька для новорождённого и прогулочный блок с полным набором механизмов. Пользовались одним ребёнком примерно восемь месяцев, дальше перешли на кресло-каталку. Колёса накачиваются, подшипники не скрипят, амортизация мягкая даже на бордюрах. В комплекте дождевик, москитная сетка, сумка для мамы. Ткань постирали перед продажей, следов протечек и запахов нет. Шасси складывается в один клик и легко влезает в багажник седана.',
     1550000, 'published', '{"category":"kids","condition":"used"}'::jsonb, true, false, now() - interval '56 days', now() - interval '56 days'),
    ('fb0d1b17-9630-50d1-8740-5b2cbccc7b1c', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000006', 'Горный велосипед, рама 19, колёса 29 дюймов',
     'Горный велосипед с алюминиевой рамой 19 дюймов и колёсами 29 дюймов, 21 скорость. Катался два сезона по лесным тропам и городу, перед продажей отдал в сервис на полное ТО: смазка цепи, регулировка тормозов и переключателей. Резина держит протектор хорошо, восьмёрок на колёсах нет. Седло эргономичное, но могу заменить на стандартное по запросу. Продаю, потому что перешёл на шоссейный велосипед — этот просто пылится в кладовке.',
     2800000, 'published', '{"category":"sport","condition":"used"}'::jsonb, true, false, now() - interval '55 days', now() - interval '55 days'),
    ('eddc7c85-9db5-5a91-b87f-f5062eb7a5dc', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000007', 'Гитара акустическая Yamaha F310, с чехлом',
     'Акустическая гитара Yamaha F310 — классика для обучения и домашней игры. Гриф ровный, лады не задевают, строй держит стабильно. Струны заменил месяц назад на комплект D''Addario, звук яркий. На нижней деке есть небольшая потёртость от ремня, на звучание не влияет, честно показал на фото. В комплекте мягкий чехол, каподастр и три медиатора. Продаю, потому что перешёл на электрогитару и акустика простаивает без дела уже полгода.',
     920000, 'published', '{"category":"music","condition":"used"}'::jsonb, true, false, now() - interval '54 days', now() - interval '54 days'),
    ('f7fdd04c-caaa-5cfe-a676-788a43aac15f', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000008', 'Собрание сочинений, набор книг в твёрдом переплёте, новое',
     'Продаю набор книг в твёрдом переплёте, восемь томов классической прозы — заказали онлайн в подарок, но подарили другое издание, а это осталось нераспечатанным. Плёнка на коробке цела, книги новые, ни разу не открывались. Обложки без единой царапины, корешки ровные, страницы белые. Формат удобный, шрифт крупный, комфортно читать вечером. Продаю всем комплектом, отдельно тома не разбиваю. Отдам дешевле магазинной цены, поскольку деньги на полку не резиновые.',
     260000, 'published', '{"category":"books","condition":"new"}'::jsonb, true, false, now() - interval '53 days', now() - interval '53 days'),
    ('89323be2-60bf-51d2-83d1-0b6c10c55668', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000009', 'Комплект летних шин 205/55 R16, 4 штуки',
     'Комплект летних шин размером 205/55 R16, четыре штуки. Отъездил на них два сезона, глубина протектора ещё около 5-6 мм по всему кругу, дисбаланса и грыж нет. Хранились в шинном отеле, не на улице, поэтому резина не задубела. Продаю в связи с продажей автомобиля, на новую машину нужен другой размер. Можно проверить протектор глубиномером при осмотре, торг уместен при покупке всего комплекта.',
     1200000, 'published', '{"category":"auto","condition":"used"}'::jsonb, true, false, now() - interval '52 days', now() - interval '52 days'),
    ('137d434e-de08-5f23-8af1-5133a4eedebc', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-00000000000a', 'Сдаю уютную студию рядом с метро, ремонт',
     'Сдаю студию 28 квадратных метров с чистовым ремонтом в шаговой доступности от метро. Есть вся необходимая техника: холодильник, стиральная машина, плита, микроволновка. Мебель новая, кровать двуспальная, есть рабочий стол для тех, кто на удалёнке. Окна выходят во двор, тихо даже вечером. Депозит стандартный — один месяц, оплата помесячно. Заселение возможно в течение недели после осмотра, документы все в порядке.',
     4200000, 'published', '{"category":"realty","condition":"used"}'::jsonb, true, false, now() - interval '51 days', now() - interval '51 days'),
    ('31a114e4-2cca-5668-9529-bd42bd790196', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-00000000000b', 'Фен Dyson Supersonic, фиолетовый, полный комплект',
     'Фен Dyson Supersonic в фиолетовом корпусе, куплен два года назад в фирменном магазине. Мощность сушки впечатляет, волосы почти не путаются благодаря ионизации. В комплекте все три насадки: для укладки, для сглаживания и диффузор для вьющихся волос. Работает исправно, перегрева и посторонних звуков не замечал. Продаю, потому что подарили новый фен на день рождения, а два в доме не нужны. Коробка и документы сохранены.',
     1950000, 'published', '{"category":"beauty","condition":"used"}'::jsonb, true, false, now() - interval '50 days', now() - interval '50 days'),
    ('6ce4938f-96e7-5f04-8aad-93d575bc53bc', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-00000000000c', 'Клетка для попугая, большая, с кормушками',
     'Просторная клетка для среднего или крупного попугая, металлический каркас с антикоррозийным покрытием. Держали жако около года, клетка в отличном состоянии — прутья не погрызены, дверца открывается свободно. В комплекте две кормушки, поилка и жёрдочки разного диаметра для разминки лап. Поддон выдвижной, чистить удобно. Продаём вместе с игрушками для попугая. Причина продажи — птицу забрали родственники в частный дом с вольером.',
     540000, 'published', '{"category":"animals","condition":"used"}'::jsonb, true, false, now() - interval '49 days', now() - interval '49 days'),
    ('ca9cc690-66ef-5a9e-9939-d3711350b435', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000001', 'Ноутбук игровой ASUS TUF Gaming, RTX, 16 ГБ',
     'Игровой ноутбук ASUS TUF Gaming с дискретной видеокартой RTX, 16 ГБ оперативной памяти и SSD на 512 ГБ. Тянет современные игры на средне-высоких настройках, для работы с графикой и монтажом тоже хватает с запасом. Экран 144 Гц, картинка плавная без разрывов. Клавиатура с RGB-подсветкой, все клавиши рабочие. Использовал полтора года, чистил систему охлаждения раз в полгода — троттлинга не было. Продаю, потому что собрал стационарный ПК.',
     6800000, 'published', '{"category":"electronics","condition":"used"}'::jsonb, true, false, now() - interval '48 days', now() - interval '48 days'),
    ('d400735c-1aef-5c5c-a022-8a29ffa2fd01', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000002', 'Микроволновка Samsung с грилем, 23 литра',
     'Микроволновая печь Samsung объёмом 23 литра с функцией гриля. Работает стабильно, разогревает и размораживает равномерно, гриль подрумянивает без подгорания. Внутри керамическое покрытие — легко моется, нагара не образует. Кнопки и таймер отзывчивые, дисплей не мигает. Продаю в связи с покупкой встраиваемой модели под новую кухню — эта отдельностоящая, а место под неё в новом гарнитуре не предусмотрено. Инструкция в комплекте.',
     490000, 'published', '{"category":"appliances","condition":"used"}'::jsonb, true, false, now() - interval '47 days', now() - interval '47 days'),
    ('93689ff8-0dee-58dd-a317-beabc637599d', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000003', 'Письменный стол дубовый, массив дерева',
     'Письменный стол из массива дуба, столешница 130 на 65 сантиметров. Использовался как рабочее место для ноутбука и документов, царапин и колец от кружек нет — всегда работал с подставкой. Ножки устойчивые, стол не шатается даже при активной работе. Есть один выдвижной ящик на направляющих без люфта. Натуральное дерево тёплого медового оттенка впишется и в классический, и в скандинавский интерьер. Продаю из-за смены рабочего места на офисное.',
     870000, 'published', '{"category":"furniture","condition":"used"}'::jsonb, true, false, now() - interval '46 days', now() - interval '46 days'),
    ('4882a5fe-d8e2-5eed-bad1-c867da73e231', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000004', 'Вечернее платье атласное, изумрудное, 44 размер',
     'Атласное вечернее платье изумрудного цвета, размер 44, длина в пол с разрезом. Надевала один раз на выпускной вечер, дефектов и затяжек нет, ткань не помялась и хранится на плечиках в чехле. Крой облегающий, подчёркивает силуэт, есть скрытая молния на спине. Подойдёт для торжества, фотосессии или выпускного. Химчистка не требуется — платье в идеальном состоянии. Продаю, потому что второй раз такое же надевать неловко, а хранить жалко выбрасывать.',
     520000, 'published', '{"category":"clothes","condition":"used"}'::jsonb, true, false, now() - interval '45 days', now() - interval '45 days'),
    ('38973565-58bd-54dc-8786-7df9216ae05b', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000005', 'Стульчик для кормления деревянный, регулируемый',
     'Деревянный стульчик для кормления с регулировкой высоты сиденья и подставки под ноги. Растёт вместе с ребёнком — можно использовать с полугода и до школьного возраста. Пластиковый поднос снимается для мытья, крепится надёжно без люфта. Дерево без сколов и заноз, покрытие лаком не облезло. Ремни безопасности пятиточечные, застёжка исправна. Продаём, потому что ребёнок подрос и уже сидит за общим столом на обычном стуле с подушкой.',
     360000, 'published', '{"category":"kids","condition":"used"}'::jsonb, true, false, now() - interval '44 days', now() - interval '44 days'),
    ('7f66dcdf-469b-5818-a3e5-177508d0895c', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000006', 'Гантели разборные, пара, до 20 кг каждая',
     'Разборные гантели, пара, максимальный вес до 20 кг на каждую с полным набором блинов. Металл, покрытие прорезиненное — не оставляет следов на полу и приятно держать в руке. Замки-барашки держат блины надёжно, за полтора года использования ни разу не откручивались сами. Идеально для домашних тренировок: жим, тяга, выпады. Продаю, потому что перешёл заниматься в зал рядом с домом и дома оборудование больше не нужно.',
     650000, 'published', '{"category":"sport","condition":"used"}'::jsonb, true, false, now() - interval '43 days', now() - interval '43 days'),
    ('3969e3c7-81b6-5a94-924b-deab715d175c', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000007', 'Синтезатор Casio, 61 клавиша, с автоаккомпанементом',
     'Синтезатор Casio на 61 полноразмерную клавишу с функцией автоаккомпанемента и записи. Множество встроенных тембров и стилей, удобно для обучения и домашних занятий. Клавиатура полувзвешенная, отклик хороший, залипаний клавиш нет. Есть выход на наушники — можно заниматься не мешая соседям. Работает от сети и от батареек, оба варианта проверены. Продаю, потому что купили более продвинутую цифровую пианино с молоточковой механикой.',
     740000, 'published', '{"category":"music","condition":"used"}'::jsonb, true, false, now() - interval '42 days', now() - interval '42 days'),
    ('dfc76291-b043-57ef-884d-a656afd2f5cc', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000008', 'Учебники за 7 класс, полный комплект',
     'Полный комплект учебников за седьмой класс по основным предметам: алгебра, геометрия, русский язык, литература, физика, биология, история. Состояние хорошее, есть небольшие карандашные пометки в паре книг, которые легко стереть ластиком. Обложки все целые, странички не вырваны. Удобно взять сразу весь комплект, чтобы не искать по отдельности перед началом учебного года. Заберём быстро — сын перешёл в следующий класс, эти учебники ему больше не нужны.',
     150000, 'published', '{"category":"books","condition":"used"}'::jsonb, true, false, now() - interval '41 days', now() - interval '41 days'),
    ('1246c47f-ac1d-53a8-a66d-daa09a5791a9', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-000000000009', 'Автомагнитола с Bluetooth и цветным экраном',
     'Автомагнитола с сенсорным цветным экраном, поддержкой Bluetooth, USB и AUX. Подключение к телефону стабильное, звук чистый без хрипов на любой громкости. Есть встроенный FM-тюнер и поддержка карт памяти до 32 ГБ. Устанавливал сам, поэтому знаю все нюансы подключения — могу проконсультировать по установке. Работала исправно весь срок использования, продаю в связи с покупкой автомобиля с магнитолой уже в базовой комплектации.',
     320000, 'published', '{"category":"auto","condition":"used"}'::jsonb, true, false, now() - interval '40 days', now() - interval '40 days'),
    ('9abf2aee-354b-5f16-9369-d6661c99d3c6', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-00000000000a', 'Сдаю комнату в трёхкомнатной квартире',
     'Сдаю светлую комнату 16 квадратных метров в трёхкомнатной квартире с двумя соседями. Мебель есть: кровать, шкаф, письменный стол, стул. Кухня и санузел общие, оба в чистом состоянии, убираемся по графику. Интернет уже подключён, платить отдельно не нужно — входит в стоимость. Рядом остановка общественного транспорта и продуктовый магазин. Ищем спокойного адекватного соседа без вредных привычек, желательно работающего или студента.',
     1400000, 'published', '{"category":"realty","condition":"used"}'::jsonb, true, false, now() - interval '39 days', now() - interval '39 days'),
    ('ba4e1660-f065-589d-a725-ce55c9f26e6b', substr(encode(gen_random_bytes(8), 'hex'), 1, 12), 'd0000000-0000-4000-a000-00000000000b', 'Фотоаппарат Canon PowerShot G7X, компактный',
